a<-commandArgs(TRUE);if(length(a)<3)stop("Usage: train_superpc.R <dev> <val> <out> [vars] [seed]");if(!requireNamespace("superpc",quietly=TRUE))stop("Install superpc");tr<-read.csv(a[1],check.names=FALSE);va<-read.csv(a[2],check.names=FALSE);out<-a[3];v<-if(length(a)>=4)strsplit(a[4],",",TRUE)[[1]]else setdiff(names(tr),c("Time","Event"));seed<-if(length(a)>=5)as.integer(a[5])else 123L;dir.create(out,recursive=TRUE,showWarnings=FALSE);mk<-function(d)list(x=t(as.matrix(d[,v,drop=FALSE])),y=d$Time,censoring.status=d$Event,featurenames=v);td<-mk(tr);vd<-mk(va);set.seed(seed);fit<-superpc::superpc.train(td,type="survival",s0.perc=.5);cv<-superpc::superpc.cv(fit,td,n.threshold=20,n.fold=10,n.components=3,min.features=min(5,length(v)),max.features=length(v),compute.fullcv=TRUE,compute.preval=TRUE);thr<-cv$thresholds[which.max(cv$scor[1,])];score<-function(d)as.numeric(superpc::superpc.predict(fit,td,d,threshold=thr,n.components=1)$v.pred);write.csv(data.frame(Time=tr$Time,Event=tr$Event,superpc=score(td)),file.path(out,"development_superpc_predictions.csv"),row.names=FALSE);write.csv(data.frame(Time=va$Time,Event=va$Event,superpc=score(vd)),file.path(out,"validation_superpc_predictions.csv"),row.names=FALSE);saveRDS(list(model=fit,cv=cv,threshold=thr,predictors=v,training_data=td),file.path(out,"superpc_model.rds"))
